#!/usr/bin/env bash
# Generated by `verdant-studio publish` from studio/src/Studio/Ops.lex.tex. Do not edit.
# A change to a reader can change what it prints for an encoding already admitted, and the studio check
# replays every admitted reader command (verify-translations). So the change re-derives those encodings
# itself: each Catalog encoding whose replay now differs is admitted again through read-admit, with the
# command and citation its admission row records, and the pull request carries both (REQ-SELF-HEALING).
# It prints each construct it admitted again, one per line.
set -euo pipefail
readers=$1
mkdir -p target
rows=$(jq length model/admissions.json)
for try in $(seq 1 "$rows"); do
  if "$readers" verify-translations model/admissions.json > target/replay.txt 2>&1; then exit 0; fi
  construct=$(sed -n 's/^\([^:]*\): its reader command now prints .*/\1/p' target/replay.txt | head -n 1)
  case "$construct" in
    Catalog.*) ;;
    *) cat target/replay.txt >&2; echo "readmit: only a Catalog encoding whose reader now prints other output is admitted again" >&2; exit 1;;
  esac
  row=$(jq -c --arg construct "$construct" '[.[] | select(.construct == $construct and .translation != null)][0]' model/admissions.json)
  authority=$(jq -r '.std.authority // ""' <<< "$row")
  cited=$(jq -r '.std.row // ""' <<< "$row")
  if [ -z "$authority" ]; then echo "readmit: $construct cites no std authority, so read-admit cannot cite it again" >&2; exit 1; fi
  mapfile -t command < <(jq -r '.translation.command[]' <<< "$row")
  "$readers" read-admit "${construct#Catalog.}" "${command[@]}" std "$authority" $cited >/dev/null
  echo "$construct"
done
echo "readmit: the replay did not settle after $rows admissions" >&2
exit 1
